4) React component with optional toggle & persistent visibility
- Drop into a React app (JSX). Stores open/closed state in localStorage.

```jsx
import { useEffect, useState } from 'react';

export default function SkillsPanel() {
  const [open, setOpen] = useState(() => {
    try { return localStorage.getItem('skillsOpen') !== 'false'; } catch { return true; }
  });

  useEffect(() => { try { localStorage.setItem('skillsOpen', String(open)); } catch{} }, [open]);

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        className="fixed left-4 bottom-4 z-50 bg-blue-600 text-white px-3 py-1 rounded"
        aria-label="Open skills"
      >
        Skills
      </button>
    );
  }

  return (
    <div className="fixed left-4 bottom-4 z-50 flex gap-2 items-center p-2 bg-white/95 rounded-md shadow">
      <button className="bg-blue-600 text-white px-3 py-1 rounded">Skill A</button>
      <button className="bg-blue-600 text-white px-3 py-1 rounded">Skill B</button>
      <button onClick={() => setOpen(false)} aria-label="Close skills" className="px-2">✕</button>
    </div>
  );
}
```

